package com.example.scanpro.data

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * Versioned, authenticated encryption for QR history (which can contain Wi-Fi passwords, tokens and addresses).
 * The key never leaves Android Keystore; a fresh random nonce is generated by Cipher for every write.
 * No app password or network dependency is needed.
 */
internal class ScanHistoryProtection(private val key: SecretKey) {
    fun seal(plaintext: String): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, key)
        val nonce = cipher.iv
        check(nonce.size == NONCE_SIZE) { "Unexpected AES-GCM nonce length" }
        return HEADER + nonce + cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))
    }

    fun open(payload: ByteArray): String {
        require(isProtected(payload)) { "Not a protected ScanPro history file" }
        require(payload.size >= HEADER.size + NONCE_SIZE + TAG_SIZE) { "Truncated history file" }
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(
            Cipher.DECRYPT_MODE,
            key,
            GCMParameterSpec(128, payload.copyOfRange(HEADER.size, HEADER.size + NONCE_SIZE))
        )
        return cipher.doFinal(payload.copyOfRange(HEADER.size + NONCE_SIZE, payload.size)).toString(Charsets.UTF_8)
    }

    companion object {
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
        private const val NONCE_SIZE = 12
        private const val TAG_SIZE = 16
        private val HEADER = byteArrayOf('S'.code.toByte(), 'P'.code.toByte(), 'H'.code.toByte(), 1)

        /** Recognise encrypted data even when truncated: never mistake it for legacy plaintext. */
        fun isProtected(payload: ByteArray): Boolean = payload.size >= HEADER.size &&
            HEADER.indices.all { payload[it] == HEADER[it] }

        /** Create or reuse the per-install key, on the history worker rather than the main thread. */
        fun fromAndroidKeystore(): ScanHistoryProtection {
            val store = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
            val existing = store.getKey(KEY_ALIAS, null) as? SecretKey
            if (existing != null) return ScanHistoryProtection(existing)
            val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
            generator.init(
                KeyGenParameterSpec.Builder(
                    KEY_ALIAS,
                    KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT
                )
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .setKeySize(256)
                    .setRandomizedEncryptionRequired(true)
                    .build()
            )
            return ScanHistoryProtection(generator.generateKey())
        }

        private const val KEY_ALIAS = "scanpro_qr_history_aes_v1"
    }
}
